import{FilterInput,SelectFilterInput,AssignedEntityFilterInput,DateFilterInput,TextFilterInput}from"/js/dist/filterInputs.min.js";import{container}from"/js/dist/simpleDIContainer.min.js";export default class FilterFormManager{constructor(){this.filters=[],this.inputs=[],this.apiService=container.resolve("apiService")}collectFilterInputs(){return this.inputs=[],document.querySelectorAll('select[id^="advancedSearch_"]').forEach((e=>{setTimeout((()=>{this.inputs.push(new SelectFilterInput(e,this.apiService))}))})),document.querySelectorAll(".input-daterange.input-group.date-range-input").forEach((e=>{this.inputs.push(new DateFilterInput(e,this.apiService))})),document.querySelectorAll('input[id^="advancedSearch_"][type="text"]').forEach((e=>{queueMicrotask((()=>{e.classList.contains("input-daterange-field")||this.inputs.push(new TextFilterInput(e,this.apiService))}))})),this.inputs}collectFilterData(){return this.filters=[],this.inputs.forEach((e=>{e.appendTo(this.filters)})),this.filters}clearAll(){this.inputs.forEach((e=>{e.clear()}))}setValuesFromResponse(e){this.clearAll();const t=[];for(const i of e){const{field:e,value:r,logic:n,operator:s}=i,l=this.inputs.find((t=>t.key===e));if(l)try{const e=l.setValue(r,n,s);e instanceof Promise&&t.push(e)}catch(t){console.error(`Failed to set value for "${e}":`,t)}else console.warn(`No input found for key: ${e}`)}return Promise.all(t).then((e=>(this.setAdvancedSearchPanelFilterEnabledState(!1),e)))}setAdvancedSearchPanelFilterEnabledState(e){queueMicrotask((()=>{const t=document.getElementById("advancedSearchPanel").getElementsByTagName("*");for(let i=0;i<t.length;i++)t[i].disabled=e}))}}
